// Strategy is the contract every sync type implements.
type Strategy interface {
	// Type returns the transform_type string this strategy handles.
	Type() string
	// ValidateSpec is called by the control plane (CMS) before a binding is
	// approved, so a malformed transform_spec is rejected early rather than at
	// runtime. A nil/empty spec is valid for strategies that need no config.
	ValidateSpec(spec []byte) error
	// BuildEmits turns one ShadowRow into zero or more master records.
	BuildEmits(rc RunContext, row ShadowRow) ([]Emit, BuildStats, error)
	// OrphanKeySuffixes returns the list of KeySuffixes that may be orphaned
	// in Master after this row was processed (i.e. array shrank).
	//
	// The engine converts each suffix to a _gpay_id via deterministicGpayID and
	// issues a single batched DELETE. This keeps all fan-out accounting logic
	// inside the strategy — the engine remains generic.
	//
	// Return nil for 1:1 strategies (no fan-out, no index-based orphans).
	// Called only when row.Deleted == false, after BuildEmits succeeds.
	OrphanKeySuffixes(rc RunContext, row ShadowRow, currentEmits []Emit) []string
}

